def solve(coins, amount):
    """
    Return the fewest number of coins (unlimited supply of each value in
    `coins`) that sum to `amount`, or -1 if it cannot be done.
    """
    if amount < 0:
        return -1
    if amount == 0:
        return 0

    INF = amount + 1
    dp = [0] + [INF] * amount

    for i in range(1, amount + 1):
        for c in coins:
            if c > 0 and c <= i and dp[i - c] + 1 < dp[i]:
                dp[i] = dp[i - c] + 1

    return dp[amount] if dp[amount] <= amount else -1

