def solve(graph, src, dst):
    """Return the length of the shortest weighted path from src to dst in a directed graph.
    `graph` is a dict mapping each node to a list of (neighbor, weight) pairs.
    Uses Dijkstra's algorithm. If dst is unreachable, returns None.
    """
    import heapq
    dist = {src: 0}
    visited = set()
    heap = [(0, src)]
    while heap:
        d, u = heapq.heappop(heap)
        if u in visited:
            continue
        visited.add(u)
        if u == dst:
            return d
        for v, w in graph.get(u, []):
            if v in visited:
                continue
            nd = d + w
            if nd < dist.get(v, float('inf')):
                dist[v] = nd
                heapq.heappush(heap, (nd, v))
    return None

