def solve(nums):
    """
    Return the length of the longest strictly increasing subsequence of nums,
    using the O(n log n) patience-sorting technique.
    """
    tails = []  # tails[k] = smallest tail of an increasing subsequence of length k+1
    for x in nums:
        # Find the leftmost position where tails[pos] >= x (strict increase).
        lo, hi = 0, len(tails)
        while lo < hi:
            mid = (lo + hi) // 2
            if tails[mid] < x:
                lo = mid + 1
            else:
                hi = mid
        if lo == len(tails):
            tails.append(x)
        else:
            tails[lo] = x
    return len(tails)

